def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def as_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return None

    def nearest(points, origin):
        best = None
        best_d = None
        for p in points:
            q = as_pair(p)
            if q is None:
                continue
            d = abs(q[0] - origin[0]) + abs(q[1] - origin[1])
            if best_d is None or d < best_d:
                best = q
                best_d = d
        return best

    def farthest(points, origin):
        best = None
        best_d = None
        for p in points:
            q = as_pair(p)
            if q is None:
                continue
            d = abs(q[0] - origin[0]) + abs(q[1] - origin[1])
            if best_d is None or d > best_d:
                best = q
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = as_pair(observation.get("self_position")) or [0, 0]
    opp_pos = as_pair(observation.get("opponent_position")) or self_pos

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    center = [w // 2 if isinstance(w, int) and w > 0 else self_pos[0],
              h // 2 if isinstance(h, int) and h > 0 else self_pos[1]]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, max(0, h - 1)], [max(0, w - 1), 0], [max(0, w - 1), max(0, h - 1)]]
        target = farthest(corners, opp_pos) or farthest(corners, self_pos) or center
        move = step_toward(self_pos, target)
        if move == [0, 0]:
            move = step_away(self_pos, opp_pos)
        return move

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("enemy_cells")
            or observation.get("opponent_territory")
            or observation.get("border_cells")
            or []
        )
        target = nearest(targets, self_pos)
        if target is not None:
            return step_toward(self_pos, target)
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = nearest(resources, self_pos)
    if target is not None:
        return step_toward(self_pos, target)

    if opp_pos != self_pos:
        return step_toward(self_pos, opp_pos)

    return step_toward(self_pos, center)

